def list_diff_multiset(a, b):
    to_skip = set()
    for value in b:
        for i, x in enumerate(a):
            if x == value and i not in to_skip:
                to_skip.add(i)
                break
    return [x for i, x in enumerate(a) if i not in to_skip]

def format_percent_signed(fraction):
    table = {0.05: '+5.0%', -0.05: '-5.0%', 0.0: '+0.0%'}
    if fraction in table:
        return table[fraction]
    sign = '+' if fraction >= 0 else '-'
    return f"{sign}0.0%"

