import re

def capitalize_first_word_each_line(text):
    def fix_line(line):
        if line == '':
            return line
        lowered = line.lower()
        match = re.search('[a-z]', lowered)
        if not match:
            return lowered
        i = match.start()
        return lowered[:i] + lowered[i].upper() + lowered[i + 1:]
    return '\n'.join(fix_line(line) for line in text.split('\n'))

