def _days_from_civil(y, m, d):
    y2 = y - (1 if m <= 2 else 0)
    era = y2 // 400
    yoe = y2 - era * 400
    mp = (m + 9) % 12
    doy = (153 * mp + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468

def first_and_last_weekday_of_month(year, month, weekday_num):
    def weekday_of(y, m, d):
        return (_days_from_civil(y, m, d) + 3) % 7

    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    dim = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1]
    first_wd = weekday_of(year, month, 1)
    first_day = 1 + (weekday_num - first_wd) % 7
    last_wd = weekday_of(year, month, dim)
    last_day = dim - (last_wd - weekday_num) % 7
    return (first_day, last_day)

def sort_by_product_of_digits(nums):
    def digit_product(x):
        p = 1
        for ch in str(x):
            p *= int(ch)
        return p

    tagged = [(digit_product(x), x) for x in nums]
    tagged.sort()
    return [x for _, x in tagged]

